@section('scripts')
<script>
(() => {
  const form=document.getElementById('v2-form'); if(!form) return;
  const csrf=document.querySelector('meta[name="csrf-token"]')?.content||form.querySelector('[name="_token"]')?.value||'';
  const panels=[...document.querySelectorAll('[data-v2-panel]')], steps=[...document.querySelectorAll('[data-v2-step]')]; let active=1;
  const persian=n=>String(n).replace(/[0-9]/g,d=>'۰۱۲۳۴۵۶۷۸۹'[d]);
  function setStep(next){active=Math.max(1,Math.min(2,next));panels.forEach(p=>p.hidden=Number(p.dataset.v2Panel)!==active);steps.forEach(s=>s.classList.toggle('is-active',Number(s.dataset.v2Step)===active));document.getElementById('v2-prev').disabled=active===1;document.getElementById('v2-next').disabled=active===2;document.getElementById('v2-next').innerHTML=active===2?'گام آخر <i class="fa-solid fa-check"></i>':'مرحلهٔ بعد <i class="fa-solid fa-arrow-left"></i>';}
  steps.forEach(s=>s.addEventListener('click',()=>setStep(Number(s.dataset.v2Step)))); document.getElementById('v2-prev').addEventListener('click',()=>setStep(active-1)); document.getElementById('v2-next').addEventListener('click',()=>setStep(active+1));
  const product=document.getElementById('v2-product'); product.addEventListener('change',()=>{if(product.value) window.location='{{ route('admin.video-studio.experimental') }}?product_id='+encodeURIComponent(product.value);});
  const hookValue=document.getElementById('v2-hook-value'),hookPreview=document.getElementById('v2-phone-hook'),hookManual=document.getElementById('v2-hook-manual'),hookScreen=document.getElementById('v2-phone-screen');
  const promptValues=@json($socialPrompts);
  const setHookText=value=>{const text=String(value||'').trim()||'یک انتخاب بهتر داشته باش';hookValue.value=text;hookPreview.textContent=text;document.querySelectorAll('.v2-font-sample').forEach(sample=>{if(sample.firstChild)sample.firstChild.textContent=text+' ';});};
  function syncHook(){const selected=document.querySelector('input[name="v2_hook_choice"]:checked');if(selected&&hookManual)hookManual.value=selected.value;setHookText(selected?.value||hookManual?.value||hookValue.value);document.querySelectorAll('.v2-hook-card').forEach(card=>card.classList.toggle('is-selected',card.querySelector('input')?.checked));}
  document.querySelectorAll('input[name="v2_hook_choice"]').forEach(input=>input.addEventListener('change',syncHook));hookManual?.addEventListener('input',()=>setHookText(hookManual.value));syncHook();
  const bgMap={primary:'var(--primary)',dark:'var(--text-h)',light:'var(--card-bg)',neutral:'var(--input-bg)'},textMap={primary:'var(--primary)',dark:'var(--text-h)',light:'var(--card-bg)',neutral:'var(--text-soft)'};
  function syncBackground(){const background=document.querySelector('input[name="v2_bg"]:checked')?.value||'primary',textColor=document.querySelector('input[name="v2_text_color"]:checked')?.value||'light',backgroundToken=bgMap[background]||bgMap.primary,textToken=textMap[textColor]||textMap.light;document.querySelectorAll('.v2-font label').forEach(label=>{label.style.setProperty('--v2-preview-bg',backgroundToken);label.style.setProperty('--v2-preview-fg',textToken);});hookScreen?.style.setProperty('--v2-hook-bg',backgroundToken);hookScreen?.style.setProperty('--v2-hook-fg',textToken);document.getElementById('v2-hook-background-value').value=background;document.getElementById('v2-hook-text-color-value').value=textColor;}
  document.querySelectorAll('input[name="v2_bg"],input[name="v2_text_color"]').forEach(input=>input.addEventListener('change',syncBackground));syncBackground();
  function syncHookStyle(){const font=document.querySelector('input[name="font_family"]:checked')?.value||'B_Yekan',size=document.getElementById('v2-hook-font-size'),scale=document.getElementById('v2-hook-scale');hookPreview.style.fontFamily="'"+font+"'";hookPreview.style.fontSize=(size?.value||36)+'px';hookPreview.style.setProperty('--v2-hook-scale',scale?.value||1);document.getElementById('v2-hook-font-size-output').textContent=persian(size?.value||36);document.getElementById('v2-hook-scale-output').textContent=persian(scale?.value||1)+'×';}
  document.querySelectorAll('input[name="font_family"]').forEach(input=>input.addEventListener('change',syncHookStyle));document.getElementById('v2-hook-font-size')?.addEventListener('input',syncHookStyle);document.getElementById('v2-hook-scale')?.addEventListener('input',syncHookStyle);syncHookStyle();
  const sourcePicker=document.getElementById('v2-source-picker'),sourceToggle=document.getElementById('v2-source-toggle'),sourcePopover=document.getElementById('v2-source-popover'),sourceSelect=document.getElementById('v2-source'),sourceFile=document.getElementById('v2-source-file'),sourceMode=document.getElementById('v2-source-mode'),sourceLabel=document.getElementById('v2-source-selection-label');
  function openSourcePicker(open){if(!sourcePicker||!sourcePopover)return;sourcePicker.classList.toggle('is-open',open);sourcePopover.hidden=!open;sourceToggle?.setAttribute('aria-expanded',String(open));}
  function setSourceMode(mode){document.querySelectorAll('[data-v2-source-mode]').forEach(button=>button.classList.toggle('is-active',button.dataset.v2SourceMode===mode));document.querySelectorAll('[data-v2-source-pane]').forEach(pane=>pane.hidden=pane.dataset.v2SourcePane!==mode);if(mode==='system'){sourceMode.value='upload';sourceSelect.value='';sourceLabel.textContent=sourceFile?.files?.[0]?.name||'انتخاب از سیستم';}else{sourceMode.value=sourceSelect.selectedOptions[0]?.dataset.sourceType||'auto';sourceLabel.textContent=sourceSelect.selectedOptions[0]?.textContent?.trim()||'انتخاب از آرشیو';}}
  sourceToggle?.addEventListener('click',()=>openSourcePicker(sourcePopover.hidden));document.querySelectorAll('[data-v2-source-mode]').forEach(button=>button.addEventListener('click',()=>setSourceMode(button.dataset.v2SourceMode)));sourceSelect?.addEventListener('change',()=>{sourceMode.value=sourceSelect.selectedOptions[0]?.dataset.sourceType||'auto';sourceLabel.textContent=sourceSelect.selectedOptions[0]?.textContent?.trim()||'انتخاب از آرشیو';openSourcePicker(false);});sourceFile?.addEventListener('change',()=>{setSourceMode('system');document.getElementById('v2-source-file-name').textContent=sourceFile.files?.[0]?.name||'فایلی انتخاب نشده است.';openSourcePicker(false);});document.addEventListener('click',event=>{if(sourcePicker&&!sourcePicker.contains(event.target))openSourcePicker(false);});
  const duration=document.getElementById('v2-transition-duration');duration?.addEventListener('input',()=>document.getElementById('v2-transition-label').textContent=String(duration.value).replace('.', '٫'));
  function captionOption(index,text,onChoose){const button=document.createElement('button'),title=document.createElement('small');button.type='button';button.className='v2-caption-option';title.textContent='گزینه '+persian(index+1);button.append(title,document.createTextNode(text));button.addEventListener('click',()=>{button.parentElement.querySelectorAll('.v2-caption-option').forEach(item=>item.classList.remove('is-selected'));button.classList.add('is-selected');onChoose(text);});return button;}
  function renderCaptionOptions(channel,options){const holder=document.querySelector('[data-v2-caption-options="'+channel+'"]'),target=form.querySelector('[name="'+(channel==='instagram'?'caption_text':channel+'_caption_text')+'"]'),values=(Array.isArray(options)?options:[]).map(value=>String(value||'').trim()).filter(Boolean).slice(0,3);if(!holder||!values.length)return;holder.replaceChildren();values.forEach((text,index)=>holder.appendChild(captionOption(index,text,value=>{if(target)target.value=value;})));holder.firstElementChild?.classList.add('is-selected');if(target)target.value=values[0];}
  function renderKeywordOptions(options,dmTemplate){const holder=document.querySelector('[data-v2-keyword-options]'),keyword=document.getElementById('v2-instagram-keyword'),reply=document.getElementById('v2-instagram-dm-template'),values=(Array.isArray(options)?options:[]).map(value=>String(value||'').trim()).filter(Boolean).slice(0,3);if(holder&&values.length){holder.replaceChildren();values.forEach((text,index)=>holder.appendChild(captionOption(index,text,value=>{if(keyword)keyword.value=value;})));holder.firstElementChild?.classList.add('is-selected');if(keyword)keyword.value=values[0];}if(reply&&dmTemplate)reply.value=dmTemplate;}
  async function requestContent(channel,button,keywordOnly=false){if(!product.value){window.alert('ابتدا یک محصول انتخاب کنید.');setStep(1);return;}const payload=new FormData();payload.append('_token',csrf);payload.append('product_id',product.value);payload.append('channel',channel);payload.append(channel+'_prompt',String(promptValues[channel]||''));if(channel==='instagram')payload.append('hook_guidelines',document.getElementById('v2-hook-guidelines')?.value||'');button.disabled=true;const old=button.innerHTML;button.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i> در حال ساخت...';try{const response=await fetch('{{ route('admin.video-studio.preview') }}',{method:'POST',headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'},body:payload});const data=await response.json();if(!response.ok)throw new Error(data.message||'ساخت محتوا ناموفق بود');if(keywordOnly)renderKeywordOptions(data.keyword_options||[],data.dm_template||'');else{renderCaptionOptions(channel,data.caption_options||[data.caption||'']);if(channel==='instagram')renderKeywordOptions(data.keyword_options||[],data.dm_template||'');}}catch(error){window.alert(error.message||'ساخت محتوا ناموفق بود.')}finally{button.disabled=false;button.innerHTML=old;}}
  document.querySelectorAll('[data-v2-generate]').forEach(button=>button.addEventListener('click',()=>requestContent(button.dataset.v2Generate,button)));document.querySelectorAll('[data-v2-generate-keyword]').forEach(button=>button.addEventListener('click',()=>requestContent(button.dataset.v2GenerateKeyword,button,true)));
  const promptsModal=document.getElementById('v2-prompts-modal'),promptInputs=[...document.querySelectorAll('[data-v2-default-prompt]')],promptGrid=promptsModal?.querySelector('.v2-prompt-grid');const openPromptModal=channel=>{promptInputs.forEach(input=>{input.value=promptValues[input.dataset.v2DefaultPrompt]||'';input.parentElement.classList.toggle('is-selected',input.dataset.v2DefaultPrompt===channel);});promptGrid?.classList.add('is-single');promptsModal?.classList.add('is-open');};document.querySelectorAll('[data-v2-prompt-settings]').forEach(button=>button.addEventListener('click',()=>openPromptModal(button.dataset.v2PromptSettings)));const closePrompts=()=>promptsModal?.classList.remove('is-open');document.getElementById('v2-close-prompts')?.addEventListener('click',closePrompts);document.getElementById('v2-cancel-prompts')?.addEventListener('click',closePrompts);promptsModal?.addEventListener('click',event=>{if(event.target===promptsModal)closePrompts()});document.getElementById('v2-save-prompts')?.addEventListener('click',async()=>{const prompts={};promptInputs.forEach(input=>prompts[input.dataset.v2DefaultPrompt]=input.value.trim());const button=document.getElementById('v2-save-prompts');button.disabled=true;try{const response=await fetch('{{ route('admin.video-studio.experimental.social-prompts.store') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({prompts})}),data=await response.json();if(!response.ok)throw new Error(data.message||'ذخیره پرامپت ناموفق بود');Object.assign(promptValues,data.prompts||prompts);closePrompts();window.alert('پرامپت این شبکه ذخیره شد.');}catch(error){window.alert(error.message||'ذخیره پرامپت ناموفق بود.')}finally{button.disabled=false;}});
  const hookPromptModal=document.getElementById('v2-hook-prompt-modal'),hookPromptText=document.getElementById('v2-hook-prompt-text'),hookGuidelines=document.getElementById('v2-hook-guidelines'),closeHookPrompt=()=>hookPromptModal?.classList.remove('is-open');document.getElementById('v2-open-hook-prompt')?.addEventListener('click',()=>{hookPromptText.value=promptValues.hook||hookGuidelines.value||'';hookPromptModal?.classList.add('is-open')});document.getElementById('v2-close-hook-prompt')?.addEventListener('click',closeHookPrompt);document.getElementById('v2-cancel-hook-prompt')?.addEventListener('click',closeHookPrompt);hookPromptModal?.addEventListener('click',event=>{if(event.target===hookPromptModal)closeHookPrompt()});document.getElementById('v2-save-hook-prompt')?.addEventListener('click',async()=>{const button=document.getElementById('v2-save-hook-prompt'),prompt=hookPromptText.value.trim();button.disabled=true;try{const response=await fetch('{{ route('admin.video-studio.experimental.social-prompts.store') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({prompts:{hook:prompt}})}),data=await response.json();if(!response.ok)throw new Error(data.message||'ذخیره پرامپت هوک ناموفق بود');promptValues.hook=(data.prompts||{}).hook??prompt;hookGuidelines.value=promptValues.hook;closeHookPrompt();window.alert('پرامپت هوک ذخیره شد.');}catch(error){window.alert(error.message||'ذخیره پرامپت هوک ناموفق بود.')}finally{button.disabled=false;}});
  document.querySelector('[data-v2-regenerate="hook"]')?.addEventListener('click',async event=>{const button=event.currentTarget;if(!product.value){window.alert('ابتدا یک محصول انتخاب کنید.');return;}const payload=new FormData();payload.append('_token',csrf);payload.append('product_id',product.value);payload.append('channel','instagram');payload.append('hook_guidelines',hookGuidelines.value||promptValues.hook||'');button.disabled=true;const old=button.innerHTML;button.innerHTML='<i class="fa-solid fa-spinner fa-spin"></i>';try{const response=await fetch('{{ route('admin.video-studio.preview') }}',{method:'POST',headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'},body:payload}),data=await response.json();if(!response.ok)throw new Error(data.message||'ساخت هوک ناموفق بود');const holder=document.getElementById('v2-hook-grid'),values=(data.hook_options||[]).map(value=>String(value||'').trim()).filter(Boolean).slice(0,3);if(holder&&values.length){holder.replaceChildren();values.forEach((text,index)=>{const label=document.createElement('label'),input=document.createElement('input'),title=document.createElement('strong'),copy=document.createElement('p');label.className='v2-hook-card';input.type='radio';input.name='v2_hook_choice';input.value=text;title.textContent='گزینه '+persian(index+1);copy.textContent=text;label.append(input,title,copy);input.addEventListener('change',syncHook);label.addEventListener('click',()=>{input.checked=true;syncHook()});holder.appendChild(label);});holder.querySelector('input')?.click();}}catch(error){window.alert(error.message||'ساخت هوک ناموفق بود.')}finally{button.disabled=false;button.innerHTML=old;}});
  const telegramButtonList=document.getElementById('v2-telegram-button-list');function addTelegramButton(){if(!telegramButtonList||telegramButtonList.querySelectorAll('[data-v2-telegram-button-row]').length>=8)return;const row=document.createElement('div');row.className='v2-telegram-button-row';row.dataset.v2TelegramButtonRow='';row.innerHTML='<input class="v2-input" name="telegram_button_label[]" placeholder="متن دکمه"><input class="v2-input" type="url" name="telegram_button_url[]" placeholder="https://..."><select class="v2-select" name="telegram_button_style[]"><option value="primary">سبز وطن</option><option value="success">سبز موفق</option><option value="danger">قرمز</option></select><input type="hidden" name="telegram_button_width[]" value="full"><button class="v2-telegram-button-remove" type="button" data-v2-remove-telegram-button aria-label="حذف دکمه"><i class="fa-solid fa-trash"></i></button>';telegramButtonList.appendChild(row);}document.getElementById('v2-add-telegram-button')?.addEventListener('click',addTelegramButton);telegramButtonList?.addEventListener('click',event=>{const remove=event.target.closest('[data-v2-remove-telegram-button]');if(remove&&telegramButtonList.querySelectorAll('[data-v2-telegram-button-row]').length>1)remove.closest('[data-v2-telegram-button-row]')?.remove();});
  const defaults=document.getElementById('v2-defaults'); document.getElementById('v2-default-toggle').addEventListener('click',()=>defaults.classList.toggle('is-open')); document.addEventListener('click',e=>{if(!defaults.contains(e.target)) defaults.classList.remove('is-open');});
  const presetKey='vatan-video-studio-presets-v2'; const serverPresets=@json($presets->mapWithKeys(fn($preset)=>[(string)$preset->id=>['name'=>$preset->name,'settings'=>$preset->settings]])); const readPresets=()=>{try{return JSON.parse(localStorage.getItem(presetKey)||'{}')}catch{return {}}}; const snapshot=()=>{const result={};[...form.elements].filter(e=>e.name&&e.type!=='file'&&e.name!=='_token'&&e.name!=='build_now').forEach(e=>{if(e.type==='radio'){if(e.checked)result[e.name]=e.value;}else if(e.type==='checkbox'){if(e.name.endsWith('[]')){result[e.name]=result[e.name]||[];if(e.checked)result[e.name].push(e.value)}else result[e.name]=e.checked}else result[e.name]=e.value});return result};
  function apply(data){Object.entries(data||{}).forEach(([name,value])=>{const els=[...form.querySelectorAll('[name="'+CSS.escape(name)+'"]')];els.forEach(e=>{if(e.type==='checkbox')e.checked=Array.isArray(value)?value.includes(e.value):Boolean(value);else if(e.type==='radio')e.checked=String(value)===e.value;else e.value=value;});});syncHook();syncBackground();syncHookStyle();form.dispatchEvent(new CustomEvent('v2:settings-applied'));}
  document.querySelectorAll('[data-v2-duplicate]').forEach(btn=>btn.addEventListener('click',()=>{if(!product.value){window.alert('برای تکثیر، ابتدا محصول مقصد را انتخاب کنید.');setStep(1);product.focus();return;}try{const data=JSON.parse(btn.dataset.v2Duplicate||'{}');apply(data);document.getElementById('v2-parent-job-id').value=data.parent_job_id||'';document.getElementById('v2-version').value=data.version||1;window.alert('تنظیمات تکثیر شد؛ محصول مقصد و منبع را بررسی و ذخیره کنید.');}catch{window.alert('تنظیمات این خروجی قابل تکثیر نیست.')}}));
  document.querySelectorAll('[data-v2-preset]').forEach(btn=>btn.addEventListener('click',()=>{const p=btn.dataset.v2Preset;const preset={fast:{transition:'cut',transition_duration:'0.2'},luxury:{transition:'fade',transition_duration:'0.8'},minimal:{transition:'fade',transition_duration:'0.5'},ad:{transition:'slide',transition_duration:'0.5'}}[p];apply(preset);defaults.classList.remove('is-open');}));
  document.querySelectorAll('[data-v2-server-preset]').forEach(btn=>btn.addEventListener('click',()=>{const preset=serverPresets[btn.dataset.v2ServerPreset];if(preset?.settings)apply(preset.settings);defaults.classList.remove('is-open');}));
  const modal=document.getElementById('v2-settings-modal'), list=document.getElementById('v2-saved-list'); const render=()=>{const local=readPresets();const rows=[...Object.entries(serverPresets).map(([id,p])=>({id,name:p.name,value:p.settings,server:true})),...Object.entries(local).map(([name,value])=>({name,value,server:false}))];list.replaceChildren();rows.forEach(item=>{const row=document.createElement('div');row.className='v2-saved-row';row.innerHTML='<span></span><span class="v2-saved-actions"><button type="button" class="v2-icon-btn" data-load title="اعمال"><i class="fa-solid fa-rotate-left"></i></button><button type="button" class="v2-icon-btn" data-rename title="تغییر نام"><i class="fa-solid fa-pen"></i></button><button type="button" class="v2-icon-btn danger" data-delete title="حذف"><i class="fa-solid fa-trash"></i></button></span>';row.querySelector('span').textContent=item.name;row.querySelector('[data-load]').onclick=()=>{apply(item.value);modal.classList.remove('is-open')};row.querySelector('[data-rename]').onclick=async()=>{const name=window.prompt('نام جدید تنظیمات:',item.name)?.trim();if(!name||name===item.name)return;if(item.server){const response=await fetch('{{ route('admin.video-studio.experimental.presets.rename', ['preset'=>'__PRESET__']) }}'.replace('__PRESET__',item.id),{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({name})});if(response.ok){const next=await response.json();serverPresets[item.id].name=next.name;render()}}else{const next=readPresets();next[name]=next[item.name];delete next[item.name];localStorage.setItem(presetKey,JSON.stringify(next));render()}};row.querySelector('[data-delete]').onclick=async()=>{if(item.server){const response=await fetch('{{ route('admin.video-studio.experimental.presets.destroy', ['preset'=>'__PRESET__']) }}'.replace('__PRESET__',item.id),{method:'DELETE',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json'}});if(response.ok){delete serverPresets[item.id];render()}}else{const next=readPresets();delete next[item.name];localStorage.setItem(presetKey,JSON.stringify(next));render()}};list.appendChild(row)});if(!list.children.length)list.innerHTML='<div class="v2-note">هنوز تنظیمی ذخیره نشده است.</div>';};
  document.getElementById('v2-open-settings').addEventListener('click',()=>{defaults.classList.remove('is-open');render();modal.classList.add('is-open')});document.getElementById('v2-close-settings').addEventListener('click',()=>modal.classList.remove('is-open'));modal.addEventListener('click',e=>{if(e.target===modal)modal.classList.remove('is-open')});document.getElementById('v2-save-preset').addEventListener('click',async()=>{const name=window.prompt('نام تنظیمات را وارد کنید:')?.trim();if(!name)return;const response=await fetch('{{ route('admin.video-studio.experimental.presets.store') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':csrf,'Accept':'application/json'},body:JSON.stringify({name,settings:snapshot()})});if(response.ok){const saved=await response.json();serverPresets[saved.id]={name:saved.name,settings:saved.settings};render()}else{const data=readPresets();data[name]=snapshot();localStorage.setItem(presetKey,JSON.stringify(data));render()}});
  function submit(build){if(!product.value){window.alert('ابتدا یک محصول انتخاب کنید.');setStep(1);return;}document.getElementById('v2-build-field').value=build?'1':'0';form.dispatchEvent(new CustomEvent('v2:before-submit'));const btn=build?document.getElementById('v2-build-now'):document.getElementById('v2-save-list');btn.disabled=true;form.submit();}
  document.getElementById('v2-save-list').addEventListener('click',()=>submit(false));document.getElementById('v2-build-now').addEventListener('click',()=>submit(true));
})();
